// 使用MY_KEYRINGS数据集查询所有相关密钥环，保持个人>团队>单位的优先级
def inputEntity = logic.param('Default').getReal()
def provide = inputEntity.get('PROVIDER')
def result = logic.param('result')

def keyringDe = sys.dataentity('Base.KEYRING')
def credentialDe = sys.dataentity('ai.AI_CREDENTIAL')

// 使用MY_KEYRINGS数据集一次查询所有相关密钥环
def kf = keyringDe.filter()
def keyringPage = kf.fetch('MY_KEYRINGS')
def allKeyrings = keyringPage.getContent()

if (!allKeyrings) {
    result.bind([])
    return
}

// 获取所有密钥环ID
def allKeyringIds = allKeyrings.collect { it.get('ID') }

// 按scope_type分组
def keyringMap = [:]
allKeyrings.each { 
    def type = it.get('SCOPE_TYPE')
    if (!keyringMap[type]) keyringMap[type] = []
    keyringMap[type].add(it.get('ID'))
}

// 按优先级匹配：个人(user) > 团队(user_group) > 单位(organization)
def priorityOrder = ['user', 'user_group', 'organization']

// 构建凭证查询条件基类 - 加上KEYRING_ID in条件，缩小扫描范围
def cf = credentialDe.filter()
// 使用or组合多个eq条件模拟in查询
cf.in('KEYRING_ID', allKeyringIds)

cf.sort('UPDATE_TIME,DESC')

if (provide) {
    // 指定provider：查询该provider的凭证，按优先级匹配一个
    cf.eq('PROVIDER', provide)
    def credentials = cf.select()

    def matched = null
    for (type in priorityOrder) {
        def ids = keyringMap[type]
        if (ids) {
            matched = credentials.find { ids.contains(it.get('KEYRING_ID')) }
            if (matched) break
        }
    }

    result.bind(matched ? [matched] : [])
} else {
    // 未指定provider：查询所有凭证，按provider分组，每个provider只保留一个最佳匹配
    def allCredentials = cf.select()

    if (!allCredentials) {
        result.bind([])
        return
    }

    // 按provider分组
    def providerGroups = [:]
    allCredentials.each { cred ->
        def prov = cred.get('PROVIDER')
        if (!providerGroups[prov]) providerGroups[prov] = []
        providerGroups[prov].add(cred)
    }

    // 对每个provider，按优先级匹配最佳凭证
    def matchedCredentials = []
    providerGroups.each { prov, creds ->
        def matched = null
        for (type in priorityOrder) {
            def ids = keyringMap[type]
            if (ids) {
                matched = creds.find { ids.contains(it.get('KEYRING_ID')) }
                if (matched) break
            }
        }
        if (matched) {
            matchedCredentials.add(matched)
        }
    }

    result.bind(matchedCredentials)
}
